JavaScript
// ==========================================================================
// 🏗 INGENIERÍA DE INTERCAMBIO Y MOVIMIENTO DE EDIFICIOS (3D <-> 3D)
// ==========================================================================
socket.on('finca:intercambiar-cimientos', async (datos) => {
    try {
        const userId = socket.usuarioId || (socket.request && socket.request.session && socket.request.session.userId);
        if (!userId) {
            socket.emit('finca:error', 'Sesión de usuario no autenticada.');
            return;
        }

        const { origenSlotId, destinoSlotId } = datos;
        if (origenSlotId === undefined || destinoSlotId === undefined) {
            socket.emit('finca:error', 'Parámetros de intercambio incompletos.');
            return;
        }

        // Buscar el documento del usuario en la base de datos (ajustar según tu modelo de datos Mongoose)
        const User = mongoose.model('User') || mongoose.model('Usuario');
        const usuario = await User.findById(userId);
        if (!usuario || !usuario.finca || !usuario.finca.edificios) {
            socket.emit('finca:error', 'No se encontró información de la finca del usuario.');
            return;
        }

        // Encontrar los edificios en los slots de origen y destino
        const edificios = usuario.finca.edificios;
        const indexOrigen = edificios.findIndex(e => (e.slotId !== undefined ? e.slotId : e.cimientoIndex) === parseInt(origenSlotId));
        const indexDestino = edificios.findIndex(e => (e.slotId !== undefined ? e.slotId : e.cimientoIndex) === parseInt(destinoSlotId));

        if (indexOrigen === -1) {
            socket.emit('finca:error', 'No se encontró un edificio en el cimiento de origen.');
            return;
        }

        // Realizar el intercambio de slots
        const tempSlot = edificios[indexOrigen].slotId !== undefined ? edificios[indexOrigen].slotId : edificios[indexOrigen].cimientoIndex;
        
        if (indexDestino !== -1) {
            // Si el destino está ocupado, intercambiamos ambos slots
            const slotDestinoActual = edificios[indexDestino].slotId !== undefined ? edificios[indexDestino].slotId : edificios[indexDestino].cimientoIndex;
            
            if (edificios[indexOrigen].slotId !== undefined) edificios[indexOrigen].slotId = slotDestinoActual;
            if (edificios[indexOrigen].cimientoIndex !== undefined) edificios[indexOrigen].cimientoIndex = slotDestinoActual;

            if (edificios[indexDestino].slotId !== undefined) edificios[indexDestino].slotId = tempSlot;
            if (edificios[indexDestino].cimientoIndex !== undefined) edificios[indexDestino].cimientoIndex = tempSlot;
        } else {
            // Si el destino está libre, simplemente movemos el edificio al nuevo slot
            if (edificios[indexOrigen].slotId !== undefined) edificios[indexOrigen].slotId = parseInt(destinoSlotId);
            if (edificios[indexOrigen].cimientoIndex !== undefined) edificios[indexOrigen].cimientoIndex = parseInt(destinoSlotId);
        }

        await usuario.save();

        // Responder al cliente con el terreno actualizado
        socket.emit('finca:intercambio-exitoso', {
            mensaje: 'Intercambio de parcelas realizado con éxito.',
            terreno: edificios
        });

    } catch (error) {
        console.error('Error al procesar el intercambio en el servidor:', error);
        socket.emit('finca:error', 'Error interno al procesar el intercambio de cimientos.');
    }
});
