const userSchema = new mongoose.Schema({
    username: { type: String, required: true, unique: true },
    poseeAldea: { type: Boolean, default: false }
});

const gameDataSchema = new mongoose.Schema({
    username: { type: String, required: true, unique: true },
    carretonCartas: {
        cartasAldea: { type: Array, default: [] },
        cartasFinca: { type: Array, default: [] },
        cartasCentral: { type: Array, default: [] }
    },
    cimientosFinca: { type: Array, default: [] },
    cimientosAldea: { type: Array, default: [] },
    almacenEdificiosDisponibles: { type: Array, default: [] }
});

const User = mongoose.model('User', userSchema);
const GameDataModel = mongoose.model('GameData', gameDataSchema);

// Caché en memoria para partidas activas
const cachePartidas = {};

// ========================================================
// CONEXIÓN A LA BASE DE DATOS
// ========================================================
mongoose.connect(process.env.MONGO_URI || 'mongodb://localhost:27017/imperio_xdpro', {
    useNewUrlParser: true,
    useUnifiedTopology: true
})
.then(() => console.log('📦 Conectado exitosamente a MongoDB'))
.catch(err => console.error('❌ Error al conectar a MongoDB:', err));

